import type { Line } from "@/scripts/pdf/lines";

let y = 0;
/** Builds a Line from [x, text] cells; y decreases with each call like a real page. */
export function line(page: number, ...cells: [number, string][]): Line {
  y -= 20;
  return {
    page,
    y,
    cells: cells.map(([x, text]) => ({ x, text })),
    text: cells.map(([, text]) => text).join(" "),
  };
}

